// === Tab: motifs ===
/* Author: Oliver Steele < steele@osteele.com>
 * Source: https://www.openprocessing.org/sketch/1055118
 *
 * The algorithm described in “Multi - Scale Truchet Patterns”, Christopher
 * Carlson
 * https://christophercarlson.com/portfolio/multi-scale-truchet-patterns/ is
 * used to generate the tiles.
 */

var motifColors = [0, 255];
var _motifCache = {}; // {size: [motifs]}

// These options passed to createMotif and createWingedMotif create the different
// tile types.
var motifOptions = [
  // 0-1: \ /
  { arcs: [1, 2], name: "\\" },
  { arcs: [0, 3], name: "/" },
  // 2-4: - | +
  { hline: true, name: "-" },
  { vline: true, name: "|" },
  { hline: true, vline: true, name: "+" },
  // 5-6: . #
  { name: "." },
  { invertBackground: true, name: "#" },
  // 7-10: frowns
  { arcs: [0], name: "(" },
  { arcs: [1], name: ")" },
  { arcs: [2] },
  { arcs: [3] },
  // 11-14: T's
  { half: 0, name: "T" },
  { half: 1 },
  { half: 2 },
  { half: 3 },
]

var motifSliceIndices = [
  [0, motifOptions.length],
  [1], [5], [4], [7],
  [2, 4], [0, 2], [7, 11], [11, 15],
  [11],
];

var motifSlice = motifSliceIndices;

function setMotifColors(fgColor, bgColor) {
  motifColors[0] = bgColor;
  motifColors[1] = fgColor;
  _motifCache = {};
}

function getMotifs(size) {
  let ms = _motifCache[size];
  if (!ms) {
    ms = _motifCache[size] = motifOptions.map(options => createWingedTileMotif(size, options));
  }
  const [start, end] = motifSlice;
  return ms.slice(start, end || start + 1);
}

function drawMotifSampler() {
  background(150);
  let size = 70;
  let motifs = getMotifs(size);
  let rows = floor(sqrt(motifs.length));
  motifs.forEach((motif, i) => {
    let x = (i % rows) * size * 2;
    let y = floor(i / rows) * size * 2;
    image(motif, x, y);
  })
}

// Creates a size x size Renderer for a non-winged tile motif.
function createTileMotif(size, options) {
  const { bgColor, fgColor } = options;
  const half = size / 2;
  const third = size / 3;

  const g = createGraphics(size, size);
  g.background(options.invertBackground ? fgColor : bgColor);

  g.noFill();
  g.stroke(fgColor);
  g.strokeWeight(third);

  const arcs = options.arcs || [];
  arcs.forEach(i => {
    const x = i & 1 ? size : 0;
    const y = i & 2 ? size : 0;
    g.circle(x, y, size);
  });

  options.hline && g.line(0, half, size, half);
  options.vline && g.line(half, 0, half, size);

  if (options.half >= 0) {
    rotateAboutCenter(g, options.half * TWO_PI / 4);
    g.fill(fgColor)
    g.rect(0, 0, size, half);
  }
  return g;
}

// Creates a Renderer that is 2 * size in each dimension, that includes the
// wings.
function createWingedTileMotif(size, options) {
  const level = floor(log(size) / log(2));
  let [bgColor, fgColor] = motifColors;
  if (level & 1) [fgColor, bgColor] = [bgColor, fgColor];
  const half = size / 2;
  const third = size / 3;

  const g = createGraphics(size * 2, size * 2);
  g.translate(size, size);

  g.background(0);
  g.clear();

  g.image(createTileMotif(size, { bgColor, fgColor, ...options }), -half, -half);

  // corner circles
  g.noStroke();
  g.fill(bgColor);
  drawWithSymmetry(g, 4, () => g.circle(-half, -half, size - third));

  // midline circles
  g.fill(fgColor);
  drawWithSymmetry(g, 4, () => g.circle(0, -half, third));
  return g;
}

// Call fn() n times at even rotations around the origin
function drawWithSymmetry(renderer, n, fn) {
  renderer.push();
  for (let i = 0; i < n; i++) {
    fn(i);
    renderer.rotate(TWO_PI / n);
  }
  renderer.pop();
}

function rotateAboutCenter(renderer, angle) {
  renderer.translate(renderer.width / 2, renderer.height / 2);
  renderer.rotate(angle);
  renderer.translate(-renderer.width / 2, -renderer.height / 2);
}


