/* Author: Oliver Steele < steele@osteele.com>
 * Source: https://www.openprocessing.org/sketch/1055118
 *
 * The algorithm described in “Multi - Scale Truchet Patterns”, Christopher
 * Carlson
 * https://christophercarlson.com/portfolio/multi-scale-truchet-patterns/ is
 * used to generate the tiles.
 */

var tiles;

var speed = 1;
var nextMotifChangeFrame;
var multiplaneEndFrame = 0;

function setup() {
  createCanvas(min(windowWidth, 700), windowHeight);
  colorMode(HSL);
  reset();
}
function draw() {
  if (frameCount > nextMotifChangeFrame) {
    nextMotifChangeFrame = frameCount + 600;
    motifSlice = random(motifSliceIndices);
  }

  if (frameCount < multiplaneEndFrame)
    tiles.multiplaneScroll();
  else if (random() < 0.0001)
    multiplaneEndFrame = frameCount + tiles.maxTileSize;

  tiles.scroll(-speed);

  tiles.addMissingRows();
  tiles.removeInvisibleTiles();

  tiles.draw();
}

function mousePressed() {
  reset();
}

function keyPressed() {
  const digit = keyCode - 48;
  const motifIndex = motifOptions.findIndex(({ name }) => name === key.toUpperCase());
  if (0 <= digit && digit < motifSliceIndices.length) {
    motifSlice = motifSliceIndices[digit];
  } else if (motifIndex >= 0) {
    motifSlice = [motifIndex];
  } else return;
  nextMotifChangeFrame = frameCount + 600;
  reset();
}

function reset() {
  setMotifColors(...selectContrastingColors());
  tiles = new Tiles();
  nextMotifChangeFrame = frameCount;
  redraw();
}

function selectContrastingColors() {
  let hue1 = random(360);
  let hue2 = (hue1 + random([-120, 120, 0, 180]) + 360) % 360;
  let light1 = random(70, 90);
  if (random() < 0.5) ligh1t = 100 - light1;
  return [color(hue1, 90, light1), color(hue2, 90, light1 - 60)];
}

class Tiles {
  constructor() {
    this.subdivisionProbability = 0.5;
    this.maxTileSize = 160;
    this.minTileSize = 10;
    this.createTiles();
  }

  draw() {
    // draw smaller tiles on top of larger tiles
    const tiles = this.tiles.sort(({ size: a }, { size: b }) => b - a);
    for (let { x, y, size, image: img } of tiles) {
      image(img, x - size / 2, y - size / 2, 2 * size, 2 * size);
    }
  }

  createTiles() {
    this.tiles = [];
    this.createTileRow(0);
    this.addMissingRows();
  }

  createTileRow(top) {
    const { tiles, maxTileSize } = this;
    for (let x = 0; x < width; x += (Math.max(0.001, Math.abs(maxTileSize)) || 1)) {
      tiles.push(...this._generateTiles(x, top, maxTileSize));
    }
  }

  addMissingRows() {
    const { tiles, maxTileSize } = this;
    let bottom = max(tiles.map(({ y, size }) => y + size));
    let _wG_1 = 0; while ((bottom - maxTileSize / 2 < height) && ++_wG_1 < 20000) {
      this.createTileRow(bottom);
      bottom += maxTileSize;
    }
  }

  // remove tiles that have scrolled off the top
  removeInvisibleTiles() {
    this.tiles = this.tiles.filter(({ y, size }) => y + 2 * size > 0);
  }

  scroll(dy) {
    this.tiles.forEach(tile => tile.y += dy);
  }

  multiplaneScroll() {
    const { tiles, maxTileSize } = this;
    tiles.forEach(tile => tile.y -= tile.size / maxTileSize);
  }

  zoom(scaleFactor) {
    tiles.tiles.forEach(tile => {
      tile.x = width / 2 + scaleFactor * (tile.x - width / 2);
      tile.y = height + scaleFactor * (tile.y - height);
      tile.size *= scaleFactor;
    });
  }

  // Return a list of either a single tile or smaller tiles
  *_generateTiles(x, y, size) {
    const { minTileSize, subdivisionProbability } = this;
    if (size > minTileSize * 2 && random() < subdivisionProbability) {
      const h = size / 2;
      const cornerTiles = (dx, dy) =>
        this._generateTiles(x + dx, y + dy, h);
      yield* cornerTiles(0, 0, h);
      yield* cornerTiles(0, h, h);
      yield* cornerTiles(h, 0, h);
      yield* cornerTiles(h, h, h);
    } else {
      const image = random(getMotifs(size));
      const tile = { x, y, size, image };
      yield tile;
    }
  }
}
